<?php
declare(strict_types=1); namespace App\Core;
class Auth { public static function check():bool{return Session::get('auth_user_id')!==null;} public static function id():?int{$v=Session::get('auth_user_id');return $v===null?null:(int)$v;} public static function name():string{return (string)Session::get('auth_user_name','');} public static function role():string{return (string)Session::get('auth_user_role','');} public static function login(int $id,string $name,string $role='User'):void{Session::start();session_regenerate_id(true);Session::set('auth_user_id',$id);Session::set('auth_user_name',$name);Session::set('auth_user_role',$role);} public static function logout():void{Session::destroy();} public static function requireLogin():void{if(!self::check()){header('Location: '.Url::to('login'));exit;}} }
